import solution
request = {
    'task': 'Create stats.py with a function mean(values). It must return the arithmetic mean of the supplied numeric values and raise ValueError when values is empty.',
    'files': {'README.md': 'Statistics helpers\n'}
}
response = solution.handle_request(request)
assert isinstance(response, dict)
assert set(response) == {'files'}
files = response['files']
assert files['README.md'] == 'Statistics helpers\n'
assert isinstance(files.get('stats.py'), str)
namespace = {}
exec(compile(files['stats.py'], 'stats.py', 'exec'), namespace)
assert namespace['mean']([2, 4, 9]) == 5
try:
    namespace['mean']([])
except ValueError:
    pass
else:
    raise AssertionError('mean([]) must raise ValueError')
print('create-module-ok')

import solution
source = '''def is_even(value):\n    return value % 2 == 1\n\ndef is_odd(value):\n    return value % 2 == 1\n'''
request = {
    'task': 'Fix is_even in parity.py so it returns True exactly for even integers. Preserve the correct behavior of is_odd and do not change unrelated files.',
    'files': {'parity.py': source, 'data.txt': 'unchanged\n'}
}
response = solution.handle_request(request)
assert set(response) == {'files'}
files = response['files']
assert files['data.txt'] == 'unchanged\n'
namespace = {}
exec(compile(files['parity.py'], 'parity.py', 'exec'), namespace)
for value in range(-8, 9):
    assert namespace['is_even'](value) is (value % 2 == 0)
    assert namespace['is_odd'](value) is (value % 2 == 1)
print('repair-ok')

